/* --- 函数实现 --- */

IPM_Point_t IPM_GetPhysicalCoord(uint8_t img_x, uint8_t img_y) {
    IPM_Point_t result = {0, 0, false};

    // 1. 内存安全保护：严格防止数组越界访问导致单片机 HardFault 死机
    if (img_x >= IPM_IMG_WIDTH || img_y >= IPM_IMG_HEIGHT) {
        return result; 
    }

    // 2. 极速查表
    int16_t real_x = ipm_table[img_y][img_x][0];
    int16_t real_y = ipm_table[img_y][img_x][1];

    // 3. 校验是否为无效区域（天空/地平线以上）
    if (real_x == IPM_INVALID_VAL || real_y == IPM_INVALID_VAL) {
        return result; // is_valid 保持 false
    }

    // 4. 返回合法数据
    result.x_mm = real_x;
    result.y_mm = real_y;
    result.is_valid = true;
    
    return result;
}


uint32_t IPM_GetDistanceSq_mm(uint8_t pt1_x, uint8_t pt1_y, uint8_t pt2_x, uint8_t pt2_y) {
    IPM_Point_t p1 = IPM_GetPhysicalCoord(pt1_x, pt1_y);
    IPM_Point_t p2 = IPM_GetPhysicalCoord(pt2_x, pt2_y);

    // 如果任何一个点是天空或者越界，无法计算距离
    if (!p1.is_valid || !p2.is_valid) {
        return 0xFFFFFFFF; 
    }

    // 注意：使用 int32_t 防止差值的平方在 int16_t 中溢出！
    int32_t dx = (int32_t)p1.x_mm - (int32_t)p2.x_mm;
    int32_t dy = (int32_t)p1.y_mm - (int32_t)p2.y_mm;

    return (uint32_t)(dx * dx + dy * dy);
}


uint32_t IPM_GetDistance_mm(uint8_t pt1_x, uint8_t pt1_y, uint8_t pt2_x, uint8_t pt2_y) {
    uint32_t dist_sq = IPM_GetDistanceSq_mm(pt1_x, pt1_y, pt2_x, pt2_y);
    
    if (dist_sq == 0xFFFFFFFF) {
        return 0xFFFFFFFF;
    }

    // 使用 math.h 的浮点开方后再转回整型
    return (uint32_t)sqrtf((float)dist_sq);
}